// ---------- Expand catalog into items: one item per skin + condition ----------
function buildSkins(catalog) {
  const items = [];
  for (const s of catalog) {
    const star = (s.type === 'knife' || s.type === 'gloves') ? '★ ' : '';
    const fullName = `${star}${s.weapon} | ${s.name}${s.phase ? ` (${s.phase})` : ''}`;
    for (const code of Object.keys(CONDITIONS)) {
      const price = s.prices[code];
      if (price == null) continue;
      items.push({
        id: `${s.id}_${code.toLowerCase()}`,
        skinId: s.id,
        weapon: s.weapon,
        name: s.name,
        phase: s.phase || null,
        fullName,
        rarity: s.rarity,
        type: s.type,
        condition: CONDITIONS[code],
        conditionCode: code,
        marketValue: price,
        value: price,
        currency: 'Coins',
        image: `assets/skins/${s.id}.png`,
        imageUrl: s.img ? `${STEAM_IMAGE_BASE}${s.img}/360fx360f` : ''
      });
    }
  }
  return items;
}

const SKINS = buildSkins(SKIN_CATALOG.concat(CUSTOM_SKINS));
